import json

# Directly access the pre-injected global `input_data` dictionary.
map_id = input_data.get('map_id')
start_x = int(input_data.get('start_x'))
start_y = int(input_data.get('start_y'))
target_x = int(input_data.get('target_x'))
target_y = int(input_data.get('target_y'))

# Database of passable tiles for 1F (0_82) and B1F (0_232) based on rigorous empirical exploration.
passable_1f = set()
for y in range(4, 8):
    for x in range(14, 32):
        passable_1f.add((x, y))

# Column 22 vertical connector on 1F
for y in range(8, 14):
    passable_1f.add((22, y))

# Row 10/11 on 1F
for y in [10, 11]:
    for x in range(20, 38):
        passable_1f.add((x, y))

# Column 37 vertical path on 1F
for y in range(2, 14):
    passable_1f.add((37, y))

# Add 1F New western section (Columns 4-7, Rows 3-21, bypass on Column 4)
for y in range(3, 22):
    passable_1f.add((4, y))
for y in range(3, 22):
    if y != 16:  # Hiker is at (5, 16)
        passable_1f.add((5, y))
for y in range(6, 14):
    passable_1f.add((6, y))
    passable_1f.add((7, y))

# 1F Southern corridor (Rows 16-21, Columns 5-17)
for y in range(16, 22):
    for x in range(5, 18):
        passable_1f.add((x, y))

# 1F Column 16 corridor
for y in range(11, 16):
    passable_1f.add((16, y))

# B1F Map Database (0_232)
passable_b1f = set()

# B1F Starting Chamber: Row 21 is a solid rock wall! Bounded on North by Row 21, so we use range(22, 31).
# We also keep Row 30 passable for the starting chamber.
for y in range(22, 31):
    for x in range(28, 38):
        passable_b1f.add((x, y))

# Ladder A at (33, 25)
passable_b1f.add((33, 25))

# Southern Corridor Rows 31-33, Columns 2-37 (Row 30 has solid rock blockages like (20,30), so we exclude Row 30)
for y in range(31, 34):
    for x in range(2, 38):
        passable_b1f.add((x, y))

# Western Connecting Passage - FIXED to exclude solid walls at Columns 18, 19, 20 on Rows 28-29.
# Row 24 and Row 30 are horizontal passable corridors.
for x in range(14, 21):
    passable_b1f.add((x, 24))
    passable_b1f.add((x, 30))
# Columns 15 and 17 are vertical passable bypasses.
for y in range(25, 30):
    passable_b1f.add((15, y))
    passable_b1f.add((17, y))

# Western Bypass Corridor Columns 20-25, Rows 21-25 (exclude 20, 21 since defeated Pokémaniac sprite stands there blocking it)
for y in range(21, 26):
    for x in range(20, 26):
        if not (x == 20 and y == 21):
            passable_b1f.add((x, y))

# Upper Bypass Corridor Rows 18-19, Columns 20-29
for y in [18, 19]:
    for x in range(20, 30):
        passable_b1f.add((x, y))

# Bridge Western Bypass Corridor and Upper Bypass Corridor at Row 20, Columns 20-25
for x in range(20, 26):
    passable_b1f.add((x, 20))

# Column 37 is BLOCKED at Rows 20 and 21 by solid wall TYPE_2889!
# It is passable on Rows 16-19 and Rows 22-33.
for y in range(16, 19 + 1):  # 16-19
    passable_b1f.add((37, y))
for y in range(22, 34):
    passable_b1f.add((37, y))

# Row 18-19 corridor extension
for y in [18, 19]:
    for x in range(30, 38):
        passable_b1f.add((x, y))

# Middle-Right Corridor Rows 10-13, Columns 26-37
for y in range(10, 14):
    for x in range(26, 38):
        passable_b1f.add((x, y))

# Row 16-17 Corridor Columns 26-35
for y in [16, 17]:
    for x in range(26, 36):
        passable_b1f.add((x, y))

# Middle-Left Corridor Rows 10-13, Columns 14-23
for y in range(10, 14):
    for x in range(14, 24):
        passable_b1f.add((x, y))

# Column 17 corridor connecting Row 11 to Row 20
for y in range(11, 21):
    passable_b1f.add((17, y))

# Northern dead-end corridor (Rows 2-9, Columns 14-23)
for y in range(2, 10):
    for x in range(14, 24):
        passable_b1f.add((x, y))

# Choose the active database
passable_set = passable_1f if map_id == '0_82' else passable_b1f

# Standard BFS Pathfinding
from collections import deque

queue = deque([(start_x, start_y, [])])
visited = {(start_x, start_y)}
found = False
buttons = []

while queue:
    curr_x, curr_y, path = queue.popleft()
    if curr_x == target_x and curr_y == target_y:
        buttons = path
        found = True
        break

    # Check neighbors: Up, Down, Left, Right
    neighbors = [
        (curr_x, curr_y - 1, 'Up'),
        (curr_x, curr_y + 1, 'Down'),
        (curr_x - 1, curr_y, 'Left'),
        (curr_x + 1, curr_y, 'Right')
    ]
    for nx, ny, move in neighbors:
        if (nx, ny) in passable_set and (nx, ny) not in visited:
            visited.add((nx, ny))
            queue.append((nx, ny, path + [move]))

if found:
    print(json.dumps(buttons))
else:
    print(json.dumps([]))
